178	const openFileDiff: Handler<FilePathParams, { ok: boolean }> = async (params, ctx) => {
179	  const workDir = ctx.requireWorkDir();
180	  const sessionId = ctx.getSessionId();
181	  if (!sessionId) {
182	    return { ok: false };
183	  }
184	
185	  const absolutePath = toAbsolute(workDir, params.filePath);
186	  if (!isInsideWorkDir(workDir, absolutePath)) {
187	    return { ok: false };
188	  }
189	  const relativePath = path.relative(workDir, absolutePath);
190	  const currentUri = vscode.Uri.file(absolutePath);
191	  const baselineUri = vscode.Uri.from({
192	    scheme: "consilium-baseline",
193	    path: "/" + relativePath,
194	    query: new URLSearchParams({ workDir, sessionId }).toString(),
195	  });
196	  await vscode.commands.executeCommand("vscode.diff", baselineUri, currentUri, `${path.basename(relativePath)} (changes from Consilium)`);
197	  return { ok: true };
198	};
