200	const saveBaselines: Handler<PathsParams, { ok: boolean }> = async (params, ctx) => {
201	  const workDir = ctx.requireWorkDir();
202	  const sessionId = ctx.getSessionId();
203	  if (!sessionId) {
204	    return { ok: false };
205	  }
206	
207	  for (const filePath of params.paths) {
208	    const absolutePath = toAbsolute(workDir, filePath);
209	    if (!isInsideWorkDir(workDir, absolutePath)) {
210	      continue;
211	    }
212	
213	    const relativePath = path.relative(workDir, absolutePath);
214	
215	    // Read current file content from disk (before modification)
216	    // If file doesn't exist, it's a new file - save empty string as baseline
217	    let content = "";
218	    if (fs.existsSync(absolutePath)) {
219	      try {
220	        content = fs.readFileSync(absolutePath, "utf-8");
221	      } catch {
222	        // If read fails, treat as new file
223	      }
224	    }
225	
226	    BaselineManager.saveBaseline(workDir, sessionId, relativePath, content);
227	  }
228	
229	  return { ok: true };
230	};
