24	function MessageList() {
25	  const { messages, isStreaming } = useChatStore();
26	
27	  // Calculate turn index for each assistant message
28	  // Turn index is 0-indexed, counting user messages
29	  const getTurnIndex = (idx: number): number | undefined => {
30	    if (messages[idx]?.role !== "assistant") return undefined;
31	    let turnCount = 0;
32	    for (let i = 0; i < idx; i++) {
33	      if (messages[i].role === "user") turnCount++;
34	    }
35	    return turnCount - 1; // 0-indexed (first turn = 0)
36	  };
37	
38	  return (
39	    <>
40	      <div className="">
41	        {messages.map((message, idx) => (
42	          <ChatMessage
43	            key={message.id}
44	            message={message}
45	            turnIndex={getTurnIndex(idx)}
46	            isStreaming={isStreaming && idx === messages.length - 1 && message.role === "assistant"}
47	          />
48	        ))}
49	      </div>
50	      <ScrollButton />
51	    </>
52	  );
53	}
